"""Время и дата голосом: «который час», «какой сегодня день».

Отдельный модуль по той же причине, что остальная логика колонки: чистый
код, проверяется без колонки, без сети и без модели.

Зачем он нужен. «Который час» - самый частый вопрос к часам, и раньше он
уходил в языковую модель, которая отвечала правдоподобно и неправильно:
модель не знает, который час, она знает, как звучит ответ. Часы, которые
врут о времени, - это не часы.

Разбор идёт в тех же словах, в которых говорит человек: «который час»,
«сколько времени», «какое сегодня число», «какой сегодня день», «что за
день». Время отвечаем словами, а не цифрами: «семь тридцать» на часах в
три часа ночи не разбудит так, как «половина четвёртого».

Проверки: python3 vendor/irene-va/jane_when.py
"""

import datetime

# Вопросы о времени суток.
_HOUR_Q = ("который час", "который сейчас час", "сколько времени",
           "что за час", "сейчас сколько", "сколько щас",
           "скажи время", "какое время", "время сейчас")
# Вопросы о дате и дне.
_DATE_Q = ("какое сегодня число", "какое число", "какой сегодня день",
           "какой сегодня день недели", "что за день", "какое число сегодня",
           "сегодня какое число", "какой день сегодня", "сегодня какой день")
_DAY_Q = ("какой сегодня день недели", "какой день недели", "что за день недели",
          "какой сегодня день", "что за день")

_WEEKDAY_FULL = ("понедельник", "вторник", "среда", "четверг", "пятница",
                 "суббота", "воскресенье")
_WEEKDAY_SHORT = ("пн", "вт", "ср", "чт", "пт", "сб", "вс")
_WEEKDAY_GEN = ("понедельника", "вторника", "среды", "четверга", "пятницы",
                "субботы", "воскресенья")
_MONTH_GEN = ("января", "февраля", "марта", "апреля", "мая", "июня", "июля",
              "августа", "сентября", "октября", "ноября", "декабря")

# Час в родительном падеже - для «половина четвёртого», «без пяти пятого».
# Раньше на каждую форму была своя функция с собственным словарём, и они
# разошлись; одна таблица не может разойтись сама.
_ORD = {1: "первого", 2: "второго", 3: "третьего", 4: "четвертого",
        5: "пятого", 6: "шестого", 7: "седьмого", 8: "восьмого",
        9: "девятого", 10: "десятого", 11: "одиннадцатого"}

# Числительные до двенадцати: часы всегда отвечаем словами.
_NUM = {0: "ноль", 1: "один час", 2: "два часа", 3: "три часа",
        4: "четыре часа", 5: "пять часов", 6: "шесть часов",
        7: "семь часов", 8: "восемь часов", 9: "девять часов",
        10: "десять часов", 11: "одиннадцать часов", 12: "двенадцать часов"}
_MIN = {0: "", 1: "одна минута", 2: "две минуты", 3: "три минуты",
        4: "четыре минуты", 5: "пять минут", 6: "шесть минут",
        7: "семь минут", 8: "восемь минут", 9: "девять минут",
        10: "десять минут", 11: "одиннадцать минут",
        12: "двенадцать минут", 13: "тринадцать минут",
        14: "четырнадцать минут", 15: "пятнадцать минут",
        16: "шестнадцать минут", 17: "семнадцать минут",
        18: "восемнадцать минут", 19: "девятнадцать минут",
        20: "двадцать минут", 30: "полчаса", 40: "сорок минут",
        50: "пятьдесят минут"}


def _clean(text):
    return " ".join(str(text or "").lower().replace("ё", "е").split())


def is_hour_question(text):
    p = _clean(text)
    return any(p.startswith(q) or (" " + q) in p for q in _HOUR_Q)


def is_date_question(text):
    p = _clean(text)
    return any(q in p for q in _DATE_Q)


def _num(n, table, one, few, many):
    n = int(n)
    if n % 10 == 1 and n % 100 != 11:
        return one
    if 2 <= n % 10 <= 4 and not 12 <= n % 100 <= 14:
        return few
    return many


def speak_hour(dt):
    """«семь тридцать», «половина четвёртого», «ровно семь»."""
    h = dt.hour
    m = dt.minute
    if m == 0:
        return "Сейчас ровно %s." % _hour(h)
    # «половина четвёртого» и «без пяти» звучат естественно только до
    # полудня; в полдень и ночью по-русски так не говорят, и там лучше
    # обычная форма, чем «без пяти часа».
    if m == 30 and 1 <= h <= 10:
        # Именно следующий: в половине восьмого наступил восьмой час.
        return "Сейчас половина %s." % _ORD[h + 1]
    if m == 15 and 1 <= h <= 10:
        return "Сейчас четверть %s." % _ORD[h + 1]
    if m == 45 and 1 <= h <= 11:
        return "Сейчас без пяти %s." % _next_hour(h)
    if m in _MIN:
        return "Сейчас %s и %s." % (_hour(h), _MIN[m])
    return "Сейчас %s и %d минут." % (_hour(h), m)


# После полудня тоже словами: «одиннадцать часов» звучит естественнее
# «11 часов», а часы - это то, где говорить надо красиво.
_NUM2 = {13: "час", 14: "два часа", 15: "три часа", 16: "четыре часа",
         17: "пять часов", 18: "шесть часов", 19: "семь часов",
         20: "восемь часов", 21: "девять часов", 22: "десять часов",
         23: "одиннадцать часов"}


def _hour(h):
    """Именительный: «семь часов», «час», «одиннадцать часов»."""
    if h == 0:
        return "ноль часов"
    if 1 <= h <= 12:
        return _NUM[h]
    return _NUM2[h]


def _next_hour(h):
    """Следующий час словами в родительном: «без пяти четвертого».

    До 11 утра: в 11:45 по-русски уже не говорят «без пяти двенадцатого»,
    да и таблица на двенадцатом часе обрывается.
    """
    return _ORD[h + 1] if 1 <= h <= 10 else ""


def _num(n, one, few, many):
    n = int(n)
    if n % 10 == 1 and n % 100 != 11:
        return one
    if 2 <= n % 10 <= 4 and not 12 <= n % 100 <= 14:
        return few
    return many


def speak_date(dt):
    """«Сегодня пятница, третье октября»."""
    return "Сегодня %s, %d %s." % (_WEEKDAY_FULL[dt.weekday()], dt.day,
                                   _MONTH_GEN[dt.month - 1])


def speak_weekday(dt):
    return "Сегодня %s." % _WEEKDAY_FULL[dt.weekday()]


def answer(text, now=None):
    """Ответ на вопрос о времени и дате. None - это не про них."""
    if is_hour_question(text):
        return speak_hour(now or datetime.datetime.now())
    if is_date_question(text):
        p = _clean(text)
        if any(q in p for q in _DAY_Q):
            return speak_weekday(now or datetime.datetime.now())
        return speak_date(now or datetime.datetime.now())
    return None


# ---------------------------------------------------------------------------
# Проверки
# ---------------------------------------------------------------------------
def selfcheck():
    fails = []

    def want(cond, msg):
        if not cond:
            fails.append(msg)

    def at(h, m=0, d=2, mon=10):
        return datetime.datetime(2026, mon, d, h, m)

    # Вопросы распознаются.
    for q in ("который час", "Который сейчас час?", "сколько времени",
              "какое время", "скажи время"):
        want(is_hour_question(q), "не узнан вопрос о времени: %s" % q)
    for q in ("какое сегодня число", "какой сегодня день",
              "какой сегодня день недели", "что за день"):
        want(is_date_question(q), "не узнан вопрос о дате: %s" % q)

    # И отвечает на них.
    want(answer("который час", at(7, 30)) == "Сейчас половина восьмого.",
         "половина восьмого: %r" % answer("который час", at(7, 30)))
    want(answer("сколько времени", at(7, 0)) == "Сейчас ровно семь часов.",
         "ровно семь: %r" % answer("сколько времени", at(7, 0)))
    want(answer("который час", at(3, 15)) == "Сейчас четверть четвертого.",
         "четверть: %r" % answer("который час", at(3, 15)))
    want(answer("который час", at(3, 45)) == "Сейчас без пяти четвертого.",
         "без пяти: %r" % answer("который час", at(3, 45)))
    want(answer("который час", at(23, 5)) ==
         "Сейчас одиннадцать часов и пять минут.",
         "полночь: %r" % answer("который час", at(23, 5)))
    want(answer("который час", at(0, 0)) == "Сейчас ровно ноль часов.",
         "полночь: %r" % answer("который час", at(0, 0)))
    want(answer("который час", at(13, 7)) == "Сейчас час и семь минут.",
         "после полудня: %r" % answer("который час", at(13, 7)))
    want(answer("который час", at(15, 12)) ==
         "Сейчас три часа и двенадцать минут.",
         "минуты словами: %r" % answer("который час", at(15, 12)))

    # Дата: 2 октября 2026 - пятница.
    want(answer("какое сегодня число", at(12, 0)) ==
         "Сегодня пятница, 2 октября.", "дата: %r" % answer("какое сегодня число", at(12, 0)))
    want(answer("какой сегодня день", at(12, 0)) == "Сегодня пятница.",
         "день недели: %r" % answer("какой сегодня день", at(12, 0)))

    # Чужой разговор не должен ловиться.
    for q in ("какая сейчас погода", "включи свет", "буди меня в 7 утра",
              "поставь таймер на пять минут"):
        want(answer(q, at(12, 0)) is None, "лишнее сработало на: %s" % q)

    # Ни одна минута не должна падать.
    for h in range(24):
        for m in (0, 1, 15, 30, 45, 59):
            got = speak_hour(at(h, m))
            want(bool(got) and got.endswith("."),
                 "часы не сказаны для %02d:%02d: %r" % (h, m, got))

    for f in fails:
        print("FAIL  " + f)
    if not fails:
        print("ok    jane_when: часы отвечают временем, а не правдоподобием")
    print("ИТОГ: провалено %d" % len(fails))
    return 1 if fails else 0


if __name__ == "__main__":
    import sys
    sys.exit(selfcheck())